      SUBROUTINE TWIT3RCC     DETERMINES CONTRIBUTION OF THIRD-ORDER TRANSFER MATRIX AND C     PARTIAL OF BEAM CENTROID TO PARTIAL OF FIRST- AND SECOND-ORDER C     TRANSFER MATRICES USING OFF-AXIS EXPANSIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U.CIN'C-----------------------------------------------------------------------CCC     CONTRIBUTION TO DERIVATIVE OF FIRST-ORDER MATRIX OFC     INDIVIDUAL ELEMENT FROM DERIVATIVE OF REFERENCE TRAJECTORYC     DISPLACEMENT AND THIRD-ORDER MATRIXC      DO 20 J = 1, 5      IND = 0      DO 10 L3 = 1, 6      DO 10 L2 = 1, L3      DO 10 L1 = 1, L2      IND = IND + 1      RT(J,L1) = RT(J,L1) + U(J,IND)*(CO(L2)*COV(L3,NV2)      1                    + COV(L2,NV2)*CO(L3))      RT(J,L2) = RT(J,L2) + U(J,IND)*(CO(L1)*COV(L3,NV2)      1                    + COV(L1,NV2)*CO(L3))      RT(J,L3) = RT(J,L3) + U(J,IND)*(CO(L1)*COV(L2,NV2)      1                    + COV(L1,NV2)*CO(L2))   10 CONTINUE   20 CONTINUECC     CONTRIBUTION TO DERIVATIVE OF SECOND-ORDER MATRIX OFC     INDIVIDUAL ELEMENT FROM DERIVATIVE OF REFERENCE TRAJECTORYC     DISPLACEMENT AND THIRD-ORDER MATRIXC      IF (NORD2 .LE. 1) GO TO 100      DO 30 J = 1, 5      DO 30 K = 1, 21      TT(J,K) = 0.0   30 CONTINUEC      DO 60 J = 1, 5      IND = 0      IND13 = 0      IND23 = 0      DO 50 L3 = 1, 6      IND12 = 0      IND13I = IND13      DO 40 L2 = 1, L3      IND13 = IND13I      IND23 = IND23 + 1      DO 40 L1 = 1, L2      IND = IND + 1      IND12 = IND12 + 1      IND13 = IND13 + 1      UFAC = U(J,IND)      IF (UFAC .NE. 0.0) THEN        TT(J,IND12) = TT(J,IND12) + UFAC*COV(L3,NV2)        TT(J,IND13) = TT(J,IND13) + UFAC*COV(L2,NV2)        TT(J,IND23) = TT(J,IND23) + UFAC*COV(L1,NV2)      ENDIF   40 CONTINUE   50 CONTINUE   60 CONTINUEC  100 RETURN      END